-- Generated by tests/integration/package_workload.py; edit numbered scenarios, then regenerate.
-- Paste this entire batch into ONE SQLQueryStress window. No GO.
-- Parameter Substitution: map TargetsJson to @InputTargets (the only input).
-- Each invocation chooses one operation; writes commit to the selected database.
SET NOCOUNT ON;
IF COALESCE(ISJSON(@InputTargets),0)<>1 THROW 51102,'Map TargetsJson to InputTargets using workload/parameters.sql.',1;
DECLARE @Operation int=ABS(CONVERT(bigint,CHECKSUM(NEWID()))) % 100;

IF @Operation<18 -- 18%: 01-pages
BEGIN
 DECLARE @g01_InputQuestionId int;
 SELECT @g01_InputQuestionId=[QuestionId]
 FROM OPENJSON(@InputTargets, 'strict $."01-pages"')
  WITH ([QuestionId] int 'strict $.QuestionId');
 DECLARE @g01_Choice int=ABS(CONVERT(bigint,CHECKSUM(NEWID()))) % 100;

 IF @g01_Choice<70 EXEC dbo.Stackish_GetQuestionPage @QuestionId=@g01_InputQuestionId,@AnswerPageSize=10,@CommentLimit=5;
 ELSE IF @g01_Choice<90 EXEC dbo.Stackish_GetPostComments @PostId=@g01_InputQuestionId,@PageSize=30;
 ELSE EXEC dbo.Stackish_GetPostVoteSummary @PostId=@g01_InputQuestionId;
END

ELSE IF @Operation<34 -- 16%: 02-discovery
BEGIN
 DECLARE @g02_Choice int=ABS(CONVERT(bigint,CHECKSUM(NEWID()))) % 100;

 IF @g02_Choice<80 EXEC dbo.Stackish_ListQuestions @Sort='newest',@PageSize=30;
 ELSE EXEC dbo.Stackish_ListQuestions @Sort='active',@PageSize=30;
END

ELSE IF @Operation<44 -- 10%: 03-users
BEGIN
 DECLARE @g03_InputUserId int;
 SELECT @g03_InputUserId=[UserId]
 FROM OPENJSON(@InputTargets, 'strict $."03-users"')
  WITH ([UserId] int 'strict $.UserId');
 DECLARE @g03_Choice int=ABS(CONVERT(bigint,CHECKSUM(NEWID()))) % 100;

 IF @g03_Choice<55 EXEC dbo.Stackish_GetUserCard @UserId=@g03_InputUserId;
 ELSE IF @g03_Choice<85 EXEC dbo.Stackish_GetUserPosts @UserId=@g03_InputUserId,@PageSize=20;
 ELSE IF @g03_Choice<95 EXEC dbo.Stackish_GetUserProfile @UserId=@g03_InputUserId,@TopCount=5;
 ELSE EXEC dbo.Stackish_ListUsers @Sort='reputation',@PageSize=20;
END

ELSE IF @Operation<52 -- 8%: 04-catalog
BEGIN
 DECLARE @g04_InputTagName nvarchar(150), @g04_InputUserId int, @g04_InputPostId int;
 SELECT @g04_InputTagName=[TagName], @g04_InputUserId=[UserId], @g04_InputPostId=[PostId]
 FROM OPENJSON(@InputTargets, 'strict $."04-catalog"')
  WITH ([PostId] int 'strict $.PostId',
   [UserId] int 'strict $.UserId',
   [TagName] nvarchar(150) 'strict $.TagName');
 DECLARE @g04_Choice int=ABS(CONVERT(bigint,CHECKSUM(NEWID()))) % 100;

 IF @g04_Choice<45 EXEC dbo.Stackish_GetTagDetail @TagName=@g04_InputTagName;
 ELSE IF @g04_Choice<75 EXEC dbo.Stackish_ListTags @NamePrefix=@g04_InputTagName,@PageSize=20;
 ELSE IF @g04_Choice<95 EXEC dbo.Stackish_GetUserBadges @UserId=@g04_InputUserId,@PageSize=20;
 ELSE EXEC dbo.Stackish_GetPostHistory @PostId=@g04_InputPostId,@PageSize=20;
END

ELSE IF @Operation<62 -- 10%: 05-counters
BEGIN
 DECLARE @g05_InputQuestionId int, @g05_InputUserId int;
 SELECT @g05_InputQuestionId=[QuestionId], @g05_InputUserId=[UserId]
 FROM OPENJSON(@InputTargets, 'strict $."05-counters"')
  WITH ([QuestionId] int 'strict $.QuestionId',
   [UserId] int 'strict $.UserId');
 DECLARE @g05_Choice int=ABS(CONVERT(bigint,CHECKSUM(NEWID()))) % 100;

 IF @g05_Choice<75 EXEC dbo.Stackish_RecordQuestionView @QuestionId=@g05_InputQuestionId;
 ELSE IF @g05_Choice<90 EXEC dbo.Stackish_RecordProfileView @UserId=@g05_InputUserId;
 ELSE EXEC dbo.Stackish_RecordUserAccess @UserId=@g05_InputUserId;
END

ELSE IF @Operation<74 -- 12%: 06-votes
BEGIN
 DECLARE @g06_InputPostId int, @g06_InputPostTypeId int, @g06_InputUserId int;
 SELECT @g06_InputPostId=[PostId], @g06_InputPostTypeId=[PostTypeId], @g06_InputUserId=[UserId]
 FROM OPENJSON(@InputTargets, 'strict $."06-votes"')
  WITH ([PostId] int 'strict $.PostId',
   [PostTypeId] int 'strict $.PostTypeId',
   [UserId] int 'strict $.UserId');
 DECLARE @g06_Choice int=ABS(CONVERT(bigint,CHECKSUM(NEWID()))) % 100;

 -- Only attributed up/down votes belong to this actor. Anonymous/zero votes stay untouched.
 IF EXISTS(SELECT 1 FROM dbo.Votes WHERE PostId=@g06_InputPostId AND UserId=@g06_InputUserId AND VoteTypeId IN(2,3))
  EXEC dbo.Stackish_RemovePostVote @PostId=@g06_InputPostId,@UserId=@g06_InputUserId;
 ELSE IF @g06_InputPostTypeId=1 AND @g06_Choice<80 EXEC dbo.Stackish_UpvoteQuestion @QuestionId=@g06_InputPostId,@UserId=@g06_InputUserId;
 ELSE IF @g06_InputPostTypeId=1 EXEC dbo.Stackish_DownvoteQuestion @QuestionId=@g06_InputPostId,@UserId=@g06_InputUserId;
 ELSE IF @g06_Choice<80 EXEC dbo.Stackish_UpvoteAnswer @AnswerId=@g06_InputPostId,@UserId=@g06_InputUserId;
 ELSE EXEC dbo.Stackish_DownvoteAnswer @AnswerId=@g06_InputPostId,@UserId=@g06_InputUserId;
END

ELSE IF @Operation<84 -- 10%: 07-content
BEGIN
 DECLARE @g07_InputQuestionId int, @g07_InputUserId int, @g07_InputTagName nvarchar(150);
 SELECT @g07_InputQuestionId=[QuestionId], @g07_InputUserId=[UserId], @g07_InputTagName=[TagName]
 FROM OPENJSON(@InputTargets, 'strict $."07-content"')
  WITH ([QuestionId] int 'strict $.QuestionId',
   [UserId] int 'strict $.UserId',
   [TagName] nvarchar(150) 'strict $.TagName');
 DECLARE @g07_Choice int=ABS(CONVERT(bigint,CHECKSUM(NEWID()))) % 100;

 DECLARE @g07_Text nvarchar(max)=CONCAT(N'Stackish content ',CONVERT(nvarchar(36),NEWID()));
 DECLARE @g07_Body nvarchar(max)=@g07_Text;
 IF ABS(CONVERT(bigint,CHECKSUM(NEWID()))) % 5=0
  SET @g07_Body=@g07_Body+REPLICATE(CONVERT(nvarchar(max),N'<p>This example describes the inputs, observed output, and the expected result so another reader can reproduce the question.</p>'),128);
 DECLARE @g07_Tags nvarchar(max)=N'<'+@g07_InputTagName+N'>';
 IF @g07_Choice<20 EXEC dbo.Stackish_CreateQuestion @UserId=@g07_InputUserId,@Title=@g07_Text,@Body=@g07_Body,@Tags=@g07_Tags;
 -- A cached open question may have closed during the run; commenting is still useful.
 ELSE IF @g07_Choice<60 AND EXISTS(SELECT 1 FROM dbo.Posts WHERE Id=@g07_InputQuestionId AND PostTypeId=1 AND ClosedDate IS NULL)
  EXEC dbo.Stackish_CreateAnswer @QuestionId=@g07_InputQuestionId,@UserId=@g07_InputUserId,@Body=@g07_Body;
 ELSE EXEC dbo.Stackish_AddComment @PostId=@g07_InputQuestionId,@UserId=@g07_InputUserId,@Text=@g07_Text;
END

ELSE IF @Operation<91 -- 7%: 08-edits
BEGIN
 DECLARE @g08_InputPostId int, @g08_InputPostTypeId int, @g08_InputUserId int, @g08_InputTag1 nvarchar(150), @g08_InputTag2 nvarchar(150);
 SELECT @g08_InputPostId=[PostId], @g08_InputPostTypeId=[PostTypeId], @g08_InputUserId=[UserId], @g08_InputTag1=[Tag1], @g08_InputTag2=[Tag2]
 FROM OPENJSON(@InputTargets, 'strict $."08-edits"')
  WITH ([PostId] int 'strict $.PostId',
   [PostTypeId] int 'strict $.PostTypeId',
   [UserId] int 'strict $.UserId',
   [Tag1] nvarchar(150) 'strict $.Tag1',
   [Tag2] nvarchar(150) 'strict $.Tag2');
 DECLARE @g08_Choice int=ABS(CONVERT(bigint,CHECKSUM(NEWID()))) % 100;

 DECLARE @g08_Text nvarchar(max)=CONCAT(N'Stackish edit ',CONVERT(nvarchar(36),NEWID()));
 DECLARE @g08_Body nvarchar(max)=@g08_Text;
 IF ABS(CONVERT(bigint,CHECKSUM(NEWID()))) % 5=0
  SET @g08_Body=@g08_Body+REPLICATE(CONVERT(nvarchar(max),N'<p>This example describes the inputs, observed output, and the expected result so another reader can reproduce the question.</p>'),128);
 IF @g08_Choice<10
  EXEC dbo.Stackish_UpdateUserProfile @UserId=@g08_InputUserId,@DisplayName=N'Stackish workload user',@AboutMe=@g08_Text;
 ELSE IF @g08_InputPostTypeId=2
  EXEC dbo.Stackish_EditAnswer @AnswerId=@g08_InputPostId,@EditorUserId=@g08_InputUserId,@Body=@g08_Body,@EditSummary=N'Workload edit';
 ELSE IF @g08_Choice<55
  EXEC dbo.Stackish_EditQuestion @QuestionId=@g08_InputPostId,@EditorUserId=@g08_InputUserId,@Title=@g08_Text,@Body=@g08_Body,@EditSummary=N'Workload edit';
 ELSE
 BEGIN
  DECLARE @g08_Tags nvarchar(max)=CASE WHEN (SELECT Tags FROM dbo.Posts WHERE Id=@g08_InputPostId)=N'<'+@g08_InputTag1+N'>'
  THEN N'<'+@g08_InputTag2+N'>' ELSE N'<'+@g08_InputTag1+N'>' END;
  EXEC dbo.Stackish_RetagQuestion @QuestionId=@g08_InputPostId,@EditorUserId=@g08_InputUserId,@Tags=@g08_Tags,@EditSummary=N'Workload retag';
 END;
END

ELSE IF @Operation<94 -- 3%: 09-maintenance
BEGIN
 DECLARE @g09_InputQuestionId int, @g09_InputAnswerId int, @g09_InputUserId int, @g09_InputRelatedQuestionId int;
 SELECT @g09_InputQuestionId=[QuestionId], @g09_InputAnswerId=[AnswerId], @g09_InputUserId=[UserId], @g09_InputRelatedQuestionId=[RelatedQuestionId]
 FROM OPENJSON(@InputTargets, 'strict $."09-maintenance"')
  WITH ([QuestionId] int 'strict $.QuestionId',
   [AnswerId] int 'strict $.AnswerId',
   [UserId] int 'strict $.UserId',
   [RelatedQuestionId] int 'strict $.RelatedQuestionId');
 DECLARE @g09_Choice int=ABS(CONVERT(bigint,CHECKSUM(NEWID()))) % 100;

 IF @g09_Choice<45
 BEGIN
  DECLARE @g09_AnswerId int=CASE WHEN (SELECT AcceptedAnswerId FROM dbo.Posts WHERE Id=@g09_InputQuestionId)=@g09_InputAnswerId THEN NULL ELSE @g09_InputAnswerId END;
  EXEC dbo.Stackish_SetAcceptedAnswer @QuestionId=@g09_InputQuestionId,@UserId=@g09_InputUserId,@AnswerId=@g09_AnswerId;
 END;
 ELSE IF @g09_Choice<75
 BEGIN
  IF (SELECT ClosedDate FROM dbo.Posts WHERE Id=@g09_InputQuestionId) IS NULL
   EXEC dbo.Stackish_CloseQuestion @QuestionId=@g09_InputQuestionId,@UserId=@g09_InputUserId,@Reason=N'Workload close';
  ELSE EXEC dbo.Stackish_ReopenQuestion @QuestionId=@g09_InputQuestionId,@UserId=@g09_InputUserId;
 END;
 ELSE
 BEGIN
  DECLARE @g09_LinkId int=(SELECT MIN(Id) FROM dbo.PostLinks WHERE PostId=@g09_InputQuestionId AND RelatedPostId=@g09_InputRelatedQuestionId AND LinkTypeId=1);
  IF @g09_LinkId IS NULL EXEC dbo.Stackish_AddQuestionLink @QuestionId=@g09_InputQuestionId,@RelatedQuestionId=@g09_InputRelatedQuestionId,@UserId=@g09_InputUserId,@LinkTypeId=1;
  ELSE EXEC dbo.Stackish_RemoveQuestionLink @LinkId=@g09_LinkId,@UserId=@g09_InputUserId;
 END;
END

