ELSE IF @Operation<100 -- 3%: 12-expensive
BEGIN
 DECLARE @g12_InputQuestionId int, @g12_InputTagName nvarchar(150), @g12_InputSearchText nvarchar(250), @g12_InputFromDate datetime, @g12_InputToDate datetime, @g12_InputBadgeName nvarchar(40);
 SELECT @g12_InputQuestionId=[QuestionId], @g12_InputTagName=[TagName], @g12_InputSearchText=[SearchText], @g12_InputFromDate=[FromDate], @g12_InputToDate=[ToDate], @g12_InputBadgeName=[BadgeName]
 FROM OPENJSON(@InputTargets, 'strict $."12-expensive"')
  WITH ([QuestionId] int 'strict $.QuestionId',
   [TagName] nvarchar(150) 'strict $.TagName',
   [SearchText] nvarchar(250) 'strict $.SearchText',
   [FromDate] datetime 'strict $.FromDate',
   [ToDate] datetime 'strict $.ToDate',
   [BadgeName] nvarchar(40) 'strict $.BadgeName');
 DECLARE @g12_Choice int=ABS(CONVERT(bigint,CHECKSUM(NEWID()))) % 100;

 IF @g12_Choice<35 EXEC dbo.Stackish_GetQuestionsByTag @TagName=@g12_InputTagName,@PageSize=20;
 ELSE IF @g12_Choice<55 EXEC dbo.Stackish_SearchQuestions @Text=@g12_InputSearchText,@FromDate=@g12_InputFromDate,@ToDate=@g12_InputToDate,@SearchBody=1,@PageSize=20;
 ELSE IF @g12_Choice<70 EXEC dbo.Stackish_GetUnansweredQuestions @TagName=@g12_InputTagName,@Mode='no_solution',@PageSize=20;
 ELSE IF @g12_Choice<80 EXEC dbo.Stackish_GetRelatedQuestions @QuestionId=@g12_InputQuestionId,@PageSize=10;
 ELSE IF @g12_Choice<90 EXEC dbo.Stackish_GetTagTopUsers @TagName=@g12_InputTagName,@PageSize=10;
 ELSE IF @g12_Choice<95 EXEC dbo.Stackish_ListBadges @PageSize=20;
 ELSE EXEC dbo.Stackish_GetBadgeRecipients @BadgeName=@g12_InputBadgeName,@PageSize=20;
END
;
